export type ParsedSealEntryInstruction<
  TProgram extends string = typeof BULLXI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    entry: TAccountMetas[0];
    gameweek: TAccountMetas[1];
    config: TAccountMetas[2];
    authority: TAccountMetas[3];
    permission: TAccountMetas[4];
    permissionProgram: TAccountMetas[5];
    ephemeralVault: TAccountMetas[6];
    magicProgram: TAccountMetas[7];
  };
  data: SealEntryInstructionData;
};

export function parseSealEntryInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSealEntryInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      entry: getNextAccount(),
      gameweek: getNextAccount(),
      config: getNextAccount(),
      authority: getNextAccount(),
      permission: getNextAccount(),
      permissionProgram: getNextAccount(),
      ephemeralVault: getNextAccount(),
      magicProgram: getNextAccount(),
    },
    data: getSealEntryInstructionDataDecoder().decode(instruction.data),
  };
}
